import{_ as a,o as t,c as r,ae as l}from"./chunks/framework.Bbra5Q_l.js";const u=JSON.parse('{"title":"总览","description":"","frontmatter":{},"headers":[],"relativePath":"overview.md","filePath":"overview.md"}'),o={name:"overview.md"};function i(s,e,p,n,c,h){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h1><p>欢迎来到 Reality，椎名绫宫的在线知识库。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>椎名绫宫邀请你完善该页面，Kira☆</p></div><h2 id="为什么创建这个平台" tabindex="-1">为什么创建这个平台 <a class="header-anchor" href="#为什么创建这个平台" aria-label="Permalink to &quot;为什么创建这个平台&quot;">​</a></h2><p>说实话，这个问题其实很简单：因为我有想要分享的东西。不管是解决问题总结出的方法，还是创作出的文字，亦或者只是心里的一些想法，我觉得它们有<strong>被看见的价值</strong>，也应该有<strong>被看见的权利</strong>。</p><p>这个平台会持续收录这些内容，当然，如果你有好的内容想要分享，也欢迎将它发布在 Reality 中。</p><blockquote><p>毕竟现实世界并不属于任何个体，而是属于每个人。</p></blockquote><h2 id="如何发布文章-文档" tabindex="-1">如何发布文章 / 文档 <a class="header-anchor" href="#如何发布文章-文档" aria-label="Permalink to &quot;如何发布文章 / 文档&quot;">​</a></h2><p>以下有两种方式供你选择。</p><ol><li><p>前往 GitHub 仓库提交</p><p>你可以访问 Reality 的 <a href="https://github.com/Teak75035/Reality" target="_blank" rel="noreferrer">GitHub 页面</a> 并通过 Pull Request 向 Reality 添加文档。</p></li><li><p>将文章 / 文档传输给椎名绫宫</p><p>如果你没有 GitHub 使用习惯或并不方便使用，你可以将它分享给椎名绫宫，由椎名绫宫添加到 Reality 内。</p><p>如果文档数量较少，也推荐使用该方法。</p><div class="tip custom-block github-alert"><p class="custom-block-title">联系方式</p><p></p><p>Telegram <a href="https://t.me/lingxianww" target="_blank" rel="noreferrer">https://t.me/lingxianww</a></p><p>工作邮箱地址 <a href="mailto:interls@qq.com" target="_blank" rel="noreferrer">interls@qq.com</a> （三个工作日内回复）</p></div></li></ol><h2 id="关于内容许可" tabindex="-1">关于内容许可 <a class="header-anchor" href="#关于内容许可" aria-label="Permalink to &quot;关于内容许可&quot;">​</a></h2><p>本项目的所有文章按照 <a href="https://creativecommons.org/licenses/by-nc-sa/4.0/deed.zh-hans" target="_blank" rel="noreferrer">CC BY-SA-NC 4.0</a> 许可证进行授权，文章内部有特殊说明的除外。</p>',12)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
